// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }
    function testFuzz_property(uint256 startTimestamp, address actor) public {
        vm.assume(startTimestamp > 0);
        vm.assume(block.number % 15 != 0);
        vm.warp(startTimestamp);
        vm.deal(actor, 20 ether);

        vm.prank(actor);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);

        // move to the next block WITHOUT changing the timestamp
        vm.roll(block.number + 1);
        vm.assume(block.number % 15 != 0);

        vm.prank(actor);
        (bool ok2,) = address(c).call{value: 10 ether}("");

        // General rule: a call in the very next block (same timestamp) must succeed,
        // because reference stores pastBlockTime = timestamp + 1. The mutant stores
        // the bare timestamp, so this second call reverts.
        assertTrue(ok2);
    }
}

