pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 blockNum, address actor) public {
        // pick any block number (wide domain), keep timestamp admissible
        blockNum = bound(blockNum, 1, type(uint256).max / 2);
        vm.assume(actor != address(c) && actor != address(0));

        // fresh state each run: pastBlockTime is 0, so any timestamp > 0 works
        uint256 ts = blockNum * 2 + 1;
        vm.warp(ts);
        vm.roll(blockNum);

        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}(hex"");
        assertTrue(ok, "fallback should succeed");

        // General rule: after a successful call, the contract's balance is 0
        // exactly when the payout condition block.number % 15 == 0 holds.
        if (blockNum % 15 == 0) {
            assertTrue(address(c).balance == 0, "must pay out on multiple of 15");
        } else {
            assertTrue(address(c).balance > 0, "must keep funds on non-multiple of 15");
        }
    }
}

