pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 seed, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        // advance to a block whose number is divisible by 15 (payout trigger)
        uint256 target = block.number + (seed % 100);
        if (target % 15 != 0) {
            target += (15 - (target % 15));
        }
        vm.roll(target);
        vm.warp(block.timestamp + 1 + (seed % 7));

        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok,) = address(c).call{value: 10 ether}("");
        assertTrue(ok);

        // General rule: at a trigger block the contract always pays out its whole
        // balance, so it must hold 0 wei afterwards.
        assertEq(address(c).balance, 0);
    }
}

