pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Caller caller;

    function setUp() public { c = new C{value: 10 ether}(); caller = new Caller(); }

    function testFuzz_property(uint256 n, uint256 t) public {
        n = bound(n, 0, 10_000);
        vm.roll(n);
        vm.warp(t);
        vm.deal(address(caller), 10 ether);
        caller.callC(c);
        if (n % 15 == 0) {
            assertTrue(address(c).balance == 0, "payout block must drain full balance");
        } else {
            assertTrue(address(c).balance == 10 ether, "non-payout block must not drain");
        }
    }
}

contract Caller {
    function callC(C c) external {
        (bool ok, ) = address(c).call{value: 10 ether}("");
        require(ok, "call failed");
    }
    receive() external payable {}
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }
    function testFuzz_property(uint256 ts, address actor) public {
        ts = bound(ts, 1, block.timestamp + 2**120);
        vm.assume(actor != address(c) && actor.code.length == 0);
        RevertingSender r = new RevertingSender();
        vm.deal(address(r), 10 ether);
        vm.roll(block.number + 1); // ensure divisible by 15 below via loop-free arithmetic
        vm.roll((block.number / 15) * 15 + 15); // block.number % 15 == 0
        vm.warp(ts);
        vm.prank(address(r));
        try r.callIn(address(c)) {
            // call succeeded
        } catch {
            // revert only possible on transfer back; fine
        }
        assertEq(c.pastBlockTime(), ts + 1);
    }
}

contract RevertingSender {
    function callIn(address target) external payable {
        target.call{value: 10 ether}("");
    }
    receive() external payable {
        revert("no payouts");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public {
        c = new C{value: 10 ether}();
        attacker = new Attacker(c);
    }

    function testFuzz_property(uint256 t, uint256 n, address actor) public {
        t = bound(t, 2, type(uint256).max - 2);
        n = bound(n, 0, type(uint256).max / 15 - 1);
        vm.assume(actor != address(0) && actor != address(c) && actor != address(attacker));

        vm.roll(n * 15);          // payout branch taken (block.number % 15 == 0)
        vm.warp(t);               // t > pastBlockTime (0)

        vm.deal(actor, 10 ether);
        vm.prank(actor);
        // Attacker accepts 10 ether, forwards it to c's fallback, but its own
        // receive() reverts, so c's transfer to msg.sender fails.
        (bool ok,) = address(attacker).call{value: 10 ether}(abi.encodeWithSignature("go()"));

        assertTrue(ok && c.pastBlockTime() == t + 1);
    }
}

contract Attacker {
    C c;
    constructor(C _c) { c = _c; }

    function go() external payable {
        address(c).fallback{value: msg.value}();
    }

    receive() external payable {
        revert(); // payout to msg.sender always fails
    }

    fallback() external payable {}
}
